/**
 * Floor map, plan import and anchor editing against the backend, with a demo fallback that renders the
 * synthetic plans when no backend is present.
 */
import { svg, type SVGTemplateResult } from 'lit';
import { del, get, patch, post, put, resourceUrl, upload } from './client';
import { isApi } from './session';
import type { Anchor, Camera, CircuitState, FloorMap, GeometryRef, PlanAsset, PlanVersion, SpatialZone } from './types';
import type { GeomLevel } from '../map/geometry';
import { demoCameras, demoFloors, demoPlan, demoSite } from '../fixtures/demo';
import type { StateKind } from '../components/sw-badge';

/** K88: own floor images as the map draws them (urls already resolved). Corners: top-left, top-right, bottom-right,
 * bottom-left in plan-normalised coordinates. */
export interface FloorImageLayer {
  off: string | null;
  on: string | null;
  corners: [number, number][];
  opacity: number;
}

export interface MapBundle {
  source: 'api' | 'demo';
  floorId: string;
  floorName: string;
  /** The floor's number (CR-009: the share dialog's default - the room's surface is on the lower floor). */
  floorLevel?: number | null;
  buildingName: string;
  siteName: string;
  /** Raster background (API) or synthetic SVG (demo). Coordinates are normalized to width/height. */
  width: number;
  height: number;
  imageUrl: string | null;
  planSvg: SVGTemplateResult | null;
  planStatus: 'published' | 'draft' | 'none';
  planVersionId: string | null;
  needsAlignment: boolean;
  anchors: Anchor[];
  /** Named rooms / areas (M13); empty when none were defined. */
  zones: SpatialZone[];
  cameras: Camera[];
  permissions: { edit: boolean; publish: boolean; import: boolean; structure: boolean };
  renderMode: 'source' | 'stylized';
  stylizedAvailable: boolean;
  /** Published period of the shown version and, when loaded at an instant, how the history was resolved (T038). */
  planPublishedAt: string | null;
  planArchivedAt: string | null;
  at: string | null;
  history: 'exact' | 'current' | null;
  historyFrom: string | null;
  haHistory: { from: string | null; to: string | null; rows: number; retention_days: number } | null;
  /** Plan Studio: the structure document of the shown version (fetched by hash) and the version's scale. */
  geometryRef: GeometryRef | null;
  scaleMPerPx: number | null;
  catalogRevision: string | null;
  levels: GeomLevel[];
  circuitStates: Record<string, CircuitState>;
  /** K88: the floor's own picture(s) - lights off / on - and where their corners sit on the plan (null = none uploaded). */
  floorImages: FloorImageLayer | null;
}

function demoBundle(floorId: string): MapBundle {
  const floor = demoFloors.find((f) => f.id === floorId) ?? demoFloors[0];
  const cams = demoCameras.filter((c) => c.floorId === floor.id);
  return {
    source: 'demo',
    floorId: floor.id,
    floorName: floor.name,
    buildingName: demoSite.building,
    siteName: demoSite.name,
    width: floor.planWidth || 1200,
    height: floor.planHeight || 800,
    imageUrl: null,
    planSvg: floor.hasPlan ? demoPlan(floor.id) : null,
    planStatus: floor.hasPlan ? 'published' : 'none',
    planVersionId: floor.hasPlan ? `demo-${floor.id}` : null,
    needsAlignment: false,
    renderMode: 'source',
    stylizedAvailable: false,
    planPublishedAt: null,
    planArchivedAt: null,
    at: null,
    history: null,
    historyFrom: null,
    haHistory: null,
    geometryRef: null,
    scaleMPerPx: null,
    catalogRevision: null,
    levels: [],
    circuitStates: {},
    floorImages: null,
    anchors: cams.map((c, i) => ({
      id: `demo-anchor-${c.id}`,
      floor_id: floor.id,
      plan_version_id: `demo-${floor.id}`,
      resource_type: 'camera',
      resource_id: c.id,
      position: { x: c.x, y: c.y },
      rotation_degrees: c.rotation,
      field_of_view_degrees: c.fov,
      coverage_radius: null,
      coverage_polygon: null,
      layer_id: 'cameras',
      label: c.name,
      revision: 1,
      effective_from: '',
      effective_to: null,
      updated_at: '',
      camera: { id: c.id, recorder_id: 'demo', channel: i + 1, name: c.name, name_source: c.name, alias: null, enabled: true, sort_order: i, grid_col_span: 1, main_track: null, sub_track: null, status: c.state === 'offline' ? 'offline' : 'online', last_seen_at: null },
    })),
    zones: [],
    cameras: [],
    permissions: { edit: true, publish: true, import: true, structure: false },
  };
}

export async function loadMap(floorId: string, draft = false, at?: string): Promise<MapBundle> {
  if (!isApi()) return demoBundle(floorId);
  const q = new URLSearchParams();
  if (draft) q.set('draft', 'true');
  if (at) q.set('at', at);
  const qs = q.toString();
  const m = await get<FloorMap>(`floors/${floorId}/map${qs ? `?${qs}` : ''}`);
  return {
    source: 'api',
    floorId: m.floor.id,
    floorName: m.floor.name,
    floorLevel: m.floor.level,
    buildingName: m.building.name,
    siteName: m.site.name,
    width: m.plan?.width_px ?? 1200,
    height: m.plan?.height_px ?? 800,
    imageUrl: m.plan ? resourceUrl(m.plan.image_url) : null,
    planSvg: null,
    planStatus: m.plan ? m.plan.status === 'published' ? 'published' : 'draft' : 'none',
    planVersionId: m.plan?.id ?? null,
    needsAlignment: m.needs_alignment,
    anchors: m.anchors,
    zones: m.zones ?? [],
    cameras: m.cameras,
    permissions: m.permissions,
    renderMode: m.plan?.render_mode === 'stylized' ? 'stylized' : 'source',
    stylizedAvailable: Boolean(m.plan?.stylized_url),
    planPublishedAt: m.plan?.published_at ?? null,
    planArchivedAt: m.plan?.archived_at ?? null,
    at: m.at ?? null,
    history: m.history ?? null,
    historyFrom: m.history_from ?? null,
    haHistory: m.ha_history ?? null,
    geometryRef: m.geometry ?? null,
    scaleMPerPx: m.plan?.scale_m_per_px ?? null,
    catalogRevision: m.catalog_revision ?? null,
    levels: m.levels ?? [],
    circuitStates: m.circuit_states ?? {},
    floorImages: m.floor_images ? { off: m.floor_images.off ? resourceUrl(m.floor_images.off) : null, on: m.floor_images.on ? resourceUrl(m.floor_images.on) : null, corners: m.floor_images.corners, opacity: m.floor_images.opacity ?? 1 } : null,
  };
}

/** Camera state for a marker: real sync status when the backend knows it, otherwise the demo state. */
export function cameraState(anchor: Anchor, demoFallback?: StateKind): StateKind {
  const cam = anchor.camera;
  if (!cam) return demoFallback ?? 'unknown';
  if (cam.status === 'online') return 'live';
  if (cam.status === 'offline') return 'offline';
  return demoFallback ?? 'unknown';
}

// ---- plans ----

export const listAssets = (floorId: string) => get<{ assets: PlanAsset[] }>(`floors/${floorId}/plan-assets`);
export const uploadAsset = (floorId: string, file: File) => {
  const form = new FormData();
  form.append('file', file, file.name);
  return upload<PlanAsset>(`floors/${floorId}/plan-assets`, form);
};
export const listVersions = (floorId: string) => get<{ versions: PlanVersion[] }>(`floors/${floorId}/plan-versions`);
export const createVersion = (floorId: string, body: { asset_id: string; page: number; rotation: number; crop?: { x: number; y: number; w: number; h: number } | null; notes?: string }) =>
  post<PlanVersion>(`floors/${floorId}/plan-versions`, body);
export const publishVersion = (versionId: string) => post<PlanVersion>(`plan-versions/${versionId}/publish`);

/** What publishing or restoring a version means: geometry changes against the published one and the fate of every placed item (T038). */
export interface VersionDiff {
  from: PlanVersion | null;
  to: PlanVersion;
  geometry: { same: boolean; changes: { field: string; from: unknown; to: unknown }[] };
  anchors: {
    total: number;
    carried: number;
    needs_alignment: number;
    items: { anchor_id: string; resource_type: 'camera' | 'ha_entity'; resource_id: string; name: string; on_version_id: string; outcome: 'carried' | 'needs_alignment' }[];
  };
}
export const versionDiff = (versionId: string, against?: string) => get<VersionDiff>(`plan-versions/${versionId}/diff${against ? `?against=${against}` : ''}`);
/** Restore an archived version as a new published copy; `revision` and the expected published id make a concurrent change a clear 409. */
export const rollbackVersion = (versionId: string, revision: number, expectedPublishedId: string | null) =>
  post<PlanVersion>(`plan-versions/${versionId}/rollback`, { revision, expected_published_id: expectedPublishedId });
export const deleteVersion = (versionId: string) => del(`plan-versions/${versionId}`);

/** The name a placed item shows: cameras keep the NVR / alias name; an HA entity shows its manual name first (R3). */
export function entityName(a: { resource_type: string; label: string | null; camera?: { name: string } | null; entity?: { name: string | null } | null; resource_id: string }): string {
  if (a.resource_type === 'camera') return a.camera?.name ?? a.label ?? a.resource_id;
  return a.label ?? a.entity?.name ?? a.resource_id;
}

// ---- anchors ----

export const createAnchor = (floorId: string, body: { resource_type: 'camera' | 'ha_entity'; resource_id: string; x: number; y: number; rotation_degrees?: number; field_of_view_degrees?: number | null; layer_id?: string; label?: string | null; level_id?: string | null; mount_height_m?: number | null; tilt_deg?: number | null }) =>
  post<Anchor>(`floors/${floorId}/anchors`, body);
/** `fromFloorId` (CR-009): the anchor belongs to a room another floor owns and is edited on this floor's map - the
 * server maps the position back to the room's home plan. */
export const updateAnchor = (id: string, body: { revision: number; x?: number; y?: number; rotation_degrees?: number; field_of_view_degrees?: number | null; label?: string | null; coverage_radius?: number | null; coverage_polygon?: [number, number][] | null; label_pos?: string; level_id?: string | null; mount_height_m?: number | null; tilt_deg?: number | null }, fromFloorId?: string) =>
  patch<Anchor>(`map-anchors/${id}${fromFloorId ? `?from_floor_id=${encodeURIComponent(fromFloorId)}` : ''}`, body);
/** S4: items placed on an earlier plan version - mapped through the crops (`crop`) or re-stamped after a visual check (`accept`). */
export const realignAnchors = (floorId: string, mode: 'crop' | 'accept') => post<{ mode: string; moved: number; skipped: number; needs_alignment: boolean }>(`floors/${floorId}/anchors/realign`, { mode });
export const deleteAnchor = (id: string, fromFloorId?: string) => del(`map-anchors/${id}${fromFloorId ? `?from_floor_id=${encodeURIComponent(fromFloorId)}` : ''}`);

// ---- cameras ----

/** CR-024: `recorders` names the recorders of the visible cameras (a recorder filter is shown only with two or more). */
export const listCameras = () => get<{ cameras: Camera[]; recorders?: { id: string; name: string }[]; recorder: { id: string; name: string; model: string | null; firmware: string | null; last_seen_at: string | null } | null; can_sync: boolean }>('cameras');
export const syncCameras = () => post<{ channels: number; created: number; updated: number; recorder: { model: string | null; firmware: string | null } }>('cameras/sync');
export const registerCamera = (body: { channel: number; alias: string }) => post<Camera>('cameras', body);
export const updateCamera = (id: string, body: { alias?: string; sort_order?: number; enabled?: boolean; grid_col_span?: number; wall_hidden?: boolean }) => patch<Camera>(`cameras/${id}`, body);

/** Plain white plan area (used only where no raster and no synthetic plan exist). */
export const blankPlan = (w: number, h: number): SVGTemplateResult => svg`<rect x="0" y="0" width=${w} height=${h} fill="var(--sw-map-bg)" />`;

/** DXF source details and options (T065): what the drawing holds, what is drawn, what is skipped. */
export interface DxfLayer {
  name: string;
  drawable: number;
  off: boolean;
  frozen: boolean;
  color: number | null;
}
export interface DxfDetails {
  asset_id: string;
  adapter: { library: string; license: string; drawable: string[]; note: string };
  info: { version: string; units_code: number; units: string; layers: DxfLayer[]; entity_counts: Record<string, number>; unsupported: Record<string, number>; extent: { minx: number; miny: number; maxx: number; maxy: number; width: number; height: number } | null; drawable: number; warnings: string[] } | null;
  options: { layers: string[] | null; units: string | null };
  render: { width: number; height: number; px_per_unit: number; units: string; meters_per_px: number | null; rendered: number; skipped: Record<string, number>; layers: string[]; partial: boolean } | null;
  units_choices: string[];
}
export const getDxf = (assetId: string) => get<DxfDetails>(`plan-assets/${assetId}/dxf`);
export const setDxf = (assetId: string, body: { layers: string[] | null; units: string | null }) => put<DxfDetails>(`plan-assets/${assetId}/dxf`, body);

